// After refactoring
function sumRange(start, end) {
  return Array.from(
    { length: end - start + 1 },
    (_, i) => start + i
  ).reduce((sum, num) => sum + num, 0);
}

// Simple Calculator
function calculator(a, b, operation) {
  switch (operation) {
    case 'add': return a + b;
    case 'subtract': return a - b;
    case 'multiply': return a * b;
    case 'divide': return b !== 0 ? a / b : 'Error';
    default: return 'Invalid operation';
  }
}

